INSERT INTO products (category_id, sku, name, slug, description, price, sale_price, stock_quantity, average_rating, review_count, featured, trending, best_seller, new_arrival, badge, active) SELECT id, 'SC-MOBILES-001', 'iPhone 15 Pro 256GB Natural Titanium', 'iphone-15-pro-256gb-natural-titanium', 'Premium 5G smartphone with vivid display, dependable battery life, fast charging, advanced camera tuning, and polished everyday performance.', 21600.00, 19872.00, 8, 4.1, 66, true, false, false, false, 'SALE', true FROM categories WHERE slug='iphone' ON DUPLICATE KEY UPDATE category_id=VALUES(category_id), name=VALUES(name), description=VALUES(description), price=VALUES(price), sale_price=VALUES(sale_price), stock_quantity=VALUES(stock_quantity), average_rating=VALUES(average_rating), review_count=VALUES(review_count), featured=VALUES(featured), trending=VALUES(trending), best_seller=VALUES(best_seller), new_arrival=VALUES(new_arrival), badge=VALUES(badge), active=true;
INSERT INTO product_images (product_id, image_url, alt_text, primary_image, sort_order) SELECT id, 'https://images.unsplash.com/photo-1511707171634-5f897ff02aa9', 'iPhone 15 Pro 256GB Natural Titanium', true, 1 FROM products WHERE slug='iphone-15-pro-256gb-natural-titanium' AND NOT EXISTS (SELECT 1 FROM product_images pi WHERE pi.product_id = products.id AND pi.primary_image = true);
